code_sketch:
import io.circe.{Codec, Decoder, Encoder}
import io.circe.generic.semiauto.deriveCodec
import java.time.Instant

case class Ticket(id: Long, createdAt: Instant)

object Ticket {
  implicit val codec: Codec[Ticket] = deriveCodec[Ticket]   // one owner, both directions
}

val json = Encoder[Ticket].apply(Ticket(1, Instant.now))
val back = Decoder[Ticket].decodeJson(json)

